                q=deque([(i,j)]); seen[i][j]=True; c=[(i,j)]
                while q:
                    a,b=q.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==val and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb)); c.append((na,nb))
                if len(c)>1 and straight(c):
                    for a,b in c: out[a][b]=2
                else:
