                        if 0<=na<H and 0<=nb<W and g[na][nb]==val and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb)); c.append((na,nb))
                rs=[p[0] for p in c]; cs=[p[1] for p in c]
